WITH flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT id, device_code, reading_ts, humidity, pressure, firmware, is_new_session, burst_id, CASE WHEN device_code RLIKE '^(DV-01|DV-02)$' THEN 'CORE' WHEN device_code RLIKE '^(DV-03|DV-04)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS device_code_zone FROM sessionized;
